namespace InventoryApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using InventoryApp.Models;

namespace InventoryApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a realistic async data-fetch delay.
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Forklift A",        Location = "Warehouse 1", LastInspected = new DateTime(2026, 5, 10) },
            new() { Id = 2, Name = "Conveyor Belt B",   Location = "Warehouse 2", LastInspected = new DateTime(2026, 4, 22) },
            new() { Id = 3, Name = "Drill Press C",     Location = "Workshop 3",  LastInspected = new DateTime(2026, 6, 1) },
            new() { Id = 4, Name = "Welding Station D", Location = "Workshop 1",  LastInspected = new DateTime(2026, 3, 15) },
            new() { Id = 5, Name = "CNC Lathe E",       Location = "Workshop 2",  LastInspected = new DateTime(2026, 5, 28) },
            new() { Id = 6, Name = "Pallet Jack F",     Location = "Warehouse 1", LastInspected = new DateTime(2026, 6, 18) },
            new() { Id = 7, Name = "Air Compressor G",  Location = "Utility Room", LastInspected = new DateTime(2026, 2, 9) },
            new() { Id = 8, Name = "Overhead Crane H",  Location = "Warehouse 3", LastInspected = new DateTime(2026, 1, 30) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistSub;

    private const string PersistKey = "equipmentItems";

    protected override async Task OnInitializedAsync()
    {
        // If the SSR pass already persisted the data, rehydrate it
        // instead of calling the service a second time.
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(PersistKey, out var persisted))
        {
            _items = persisted;
        }
        else
        {
            _items = await EquipmentSvc.GetEquipmentAsync();
        }

        // Register a callback so the SSR pass serialises the data
        // into the page for the interactive runtime to pick up.
        _persistSub = ApplicationState.RegisterOnPersisting(() =>
        {
            ApplicationState.PersistAsJson(PersistKey, _items);
            return Task.CompletedTask;
        });
    }

    public void Dispose()
    {
        _persistSub.Dispose();
    }
}

